// Generated by OrchestKit Claude Plugin
// Created: 2026-11-26

/**
 * One `/goal` run: its history rows and its brake file (#4684, option A).
 *
 * A run is keyed on `prompt_id`. Measured on CC 2.1.332: a /goal continuation
 * fires no UserPromptSubmit, `prompt_id` stays the same on every tool call and
 * Stop of the run, and `stop_hook_active` is true on every continuation.
 *
 * `.claude/state/goal-history.jsonl` is append-only:
 *   start  {session_id, prompt_id, condition, started_*, ended_at: null}
 *   tally  {kind: 'tally', session_id, prompt_id, turn_count, ...}   one per Stop
 *   rekey  {kind: 'rekey', session_id, prompt_id}   a task notification moved the run
 *   end    {session_id, prompt_id, ended_at, turn_count, status}
 *
 * Writers: prompt/goal-tracker (start, end), stop/goal-tracker (tally, brake),
 * lifecycle/goal-budget-guard (end). Reader of the brake: pretool/tool-dispatcher.
 */

import { appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import type { HookInput, HookResult } from '../types.js';
import { outputDeny } from './output.js';

const STATE_REL = join('.claude', 'state');

export type GoalCapReason = 'turns_cap' | 'tokens_cap';
export type GoalStatus = 'braked' | 'ended' | 'aborted';

export interface GoalStart {
  session_id: string;
  prompt_id?: string;
  condition?: string;
  started_at?: string;
  started_token_estimate?: number;
  /** Accumulator tokens when the run opened: baseline for spend (#3317). */
  started_tokens?: number;
}

export interface GoalTally {
  turn_count: number;
  ended_token_estimate: number;
  /** Set on the Stop that tripped the cap, and carried after: one trip per run. */
  tripped?: GoalCapReason;
}

export interface OpenRun {
  start: GoalStart;
  tally: GoalTally | null;
}

export interface GoalBrake {
  tripped_at: string;
  session_id: string;
  prompt_id?: string;
  reason: GoalCapReason;
  turns: number;
  tokens: number;
  cap: number;
}

type Row = GoalStart & Partial<GoalTally> & { kind?: string; ended_at?: string | null };

export function historyPath(projectDir: string): string {
  return join(projectDir, STATE_REL, 'goal-history.jsonl');
}

/** One file per session, so a second /goal in the same project cannot release the first. */
function brakeName(sessionId: string): string {
  return `goal-budget-tripped.${sessionId.replace(/[^A-Za-z0-9_-]/g, '_')}.json`;
}

export function brakePath(projectDir: string, sessionId: string): string {
  return join(projectDir, STATE_REL, brakeName(sessionId));
}

export function readHistory(projectDir: string): string | null {
  const path = historyPath(projectDir);
  return existsSync(path) ? readFileSync(path, 'utf8') : null;
}

export function appendHistory(projectDir: string, row: object): void {
  const path = historyPath(projectDir);
  mkdirSync(dirname(path), { recursive: true });
  appendFileSync(path, `${JSON.stringify(row)}\n`, 'utf8');
}

/** The session's latest run that has no end row, with its latest tally. */
export function findOpenRun(contents: string, sessionId: string): OpenRun | null {
  let open: OpenRun | null = null;
  for (const line of contents.split(/\r?\n/)) {
    if (!line.trim()) continue;
    let row: Row;
    try {
      row = JSON.parse(line) as Row;
    } catch {
      continue;
    }
    if (row?.session_id !== sessionId) continue;
    if (row.ended_at) {
      open = null;
    } else if (row.kind === 'rekey') {
      if (open) open.start = { ...open.start, prompt_id: row.prompt_id };
    } else if (row.kind !== 'tally') {
      open = { start: row, tally: null };
    } else if (open && row.prompt_id === open.start.prompt_id) {
      open.tally = {
        turn_count: row.turn_count ?? 0,
        ended_token_estimate: row.ended_token_estimate ?? 0,
        tripped: row.tripped,
      };
    }
  }
  return open;
}

/** Append the end row of an open run, with status read from its last tally. */
export function closeRun(projectDir: string, run: OpenRun): GoalStatus {
  const turns = run.tally?.turn_count ?? 0;
  const status: GoalStatus = run.tally?.tripped ? 'braked' : turns === 0 ? 'aborted' : 'ended';
  appendHistory(projectDir, {
    session_id: run.start.session_id,
    prompt_id: run.start.prompt_id,
    ended_at: new Date().toISOString(),
    turn_count: turns,
    ended_token_estimate: run.tally?.ended_token_estimate ?? run.start.started_token_estimate ?? 0,
    status,
  });
  return status;
}

export function writeBrake(projectDir: string, brake: GoalBrake): void {
  const path = brakePath(projectDir, brake.session_id);
  mkdirSync(dirname(path), { recursive: true });
  // Rename into place: a kill mid-write never leaves a half brake file.
  const draft = `${path}.${process.pid}.tmp`;
  writeFileSync(draft, JSON.stringify(brake, null, 2));
  renameSync(draft, path);
}

function readBrake(projectDir: string, sessionId: string): GoalBrake | null {
  const path = brakePath(projectDir, sessionId);
  if (!existsSync(path)) return null;
  return JSON.parse(readFileSync(path, 'utf8')) as GoalBrake;
}

/**
 * Move an open run, and its brake if one is still on disk, to a new prompt_id.
 * For a turn CC starts itself (a task notification): same run, new id.
 */
export function carryRun(projectDir: string, run: OpenRun, promptId: string): void {
  const sessionId = run.start.session_id;
  // Brake first: a kill before the history row leaves the call denied, not free.
  const brake = readBrake(projectDir, sessionId);
  if (brake) writeBrake(projectDir, { ...brake, prompt_id: promptId });
  appendHistory(projectDir, { kind: 'rekey', session_id: sessionId, prompt_id: promptId });
}

export function removeBrake(projectDir: string, sessionId: string): void {
  rmSync(brakePath(projectDir, sessionId), { force: true });
}

/**
 * The PreToolUse verdict for a tripped run, or null to let the call through.
 * One stat when no brake exists. A brake file for this session that cannot be
 * read or lacks its ids denies: it is evidence of a trip that nothing can
 * check. A payload without session_id or prompt_id has no file to match and
 * passes.
 *
 * Deny plus `continue: false` (outputDeny). A deny alone did not end a /goal
 * run: measured on CC 2.1.332, it looped until the 9 Stop-block cap. The
 * end-to-end stop from `continue: false` follows the hook docs and has not been
 * measured on a live /goal run.
 * The reason never repeats the /goal condition (CC 2.1.328 matched hooks
 * with identical wording).
 */
export function goalBrakeVerdict(input: HookInput, projectDir: string): HookResult | null {
  const { session_id: sessionId, prompt_id: promptId } = input;
  if (!sessionId || !promptId) return null;
  const file = `.claude/state/${brakeName(sessionId)}`;
  let brake: GoalBrake | null;
  try {
    if (!existsSync(brakePath(projectDir, sessionId))) return null;
    brake = readBrake(projectDir, sessionId);
  } catch {
    brake = null;
  }
  if (!brake || typeof brake.session_id !== 'string' || typeof brake.prompt_id !== 'string') {
    return outputDeny(
      `[ork goal-budget] Tool calls are paused: ${file} cannot be read. Delete it, or send a new message, to go on.`,
    );
  }
  if (brake.session_id !== sessionId || brake.prompt_id !== promptId) return null;

  const unit = brake.reason === 'tokens_cap' ? 'token' : 'turn';
  const used = brake.reason === 'tokens_cap' ? brake.tokens : brake.turns;
  return outputDeny(
    `[ork goal-budget] Tool calls are paused: this goal run used ${used} ${unit}${used === 1 ? '' : 's'} ` +
      `(cap ${brake.cap}). Run /goal clear, or delete ${file} to go on.`,
  );
}
